// Strategy pattern: the intersection does not care HOW durations are decided
public interface SignalTimingStrategy {
    int getDurationSeconds(SignalColor color);
}

// One concrete strategy: fixed, pre-configured durations per color
class FixedTimingStrategy implements SignalTimingStrategy {
    private final Map<SignalColor, Integer> durations;

    public FixedTimingStrategy() {
        durations = new HashMap<>();
        durations.put(SignalColor.GREEN, 25);
        durations.put(SignalColor.YELLOW, 4);
        durations.put(SignalColor.RED, 30);
    }

    @Override
    public int getDurationSeconds(SignalColor color) {
        if (!durations.containsKey(color)) {
            throw new IllegalStateException("No duration configured for " + color);
        }
        return durations.get(color);
    }
}

