import java.util.ArrayList;
import java.util.List;

// TrafficSignal ties together a State (current color), a Strategy (timing),
// and a list of Observers (things that react to a change)
public class TrafficSignal {
    private final String id;
    private SignalState state;
    private final SignalTimingStrategy timingStrategy;
    private final List<SignalObserver> observers = new ArrayList<>();

    public TrafficSignal(String id, SignalTimingStrategy timingStrategy) {
        this.id = id;
        this.timingStrategy = timingStrategy;
        this.state = new RedState(); // every signal starts safely at red
    }

    public void addObserver(SignalObserver observer) {
        observers.add(observer);
    }

    public void advance() {
        state = state.next();
        notifyObservers();
    }

    public void forceState(SignalState newState) {
        state = newState;
        notifyObservers();
    }

    private void notifyObservers() {
        for (SignalObserver observer : observers) {
            observer.onSignalChange(id, state.getColor());
        }
    }

    public SignalColor getCurrentColor() {
        return state.getColor();
    }

    public int getCurrentDurationSeconds() {
        return timingStrategy.getDurationSeconds(state.getColor());
    }

    public String getId() {
        return id;
    }
}

