// Drives a 4-phase cycle and enforces the intersection's core safety invariant:
// North-South and East-West are NEVER both green at the same time
public class IntersectionController {
    private final TrafficSignal northSouthSignal;
    private final TrafficSignal eastWestSignal;
    private int phase; // 0=NS green, 1=NS yellow, 2=EW green, 3=EW yellow

    public IntersectionController(TrafficSignal northSouthSignal, TrafficSignal eastWestSignal) {
        this.northSouthSignal = northSouthSignal;
        this.eastWestSignal = eastWestSignal;
        this.phase = 0;
        applyPhase();
    }

    private void applyPhase() {
        switch (phase) {
            case 0:
                northSouthSignal.forceState(new GreenState());
                eastWestSignal.forceState(new RedState());
                break;
            case 1:
                northSouthSignal.forceState(new YellowState());
                eastWestSignal.forceState(new RedState());
                break;
            case 2:
                northSouthSignal.forceState(new RedState());
                eastWestSignal.forceState(new GreenState());
                break;
            case 3:
                northSouthSignal.forceState(new RedState());
                eastWestSignal.forceState(new YellowState());
                break;
        }
    }

    public void step() {
        phase = (phase + 1) % 4;
        applyPhase();
    }
}

