    TrafficSignal(string id, shared_ptr<SignalTimingStrategy> timingStrategy)
        : id(id), timingStrategy(timingStrategy), state(make_shared<RedState>()) {}

    void addObserver(shared_ptr<SignalObserver> observer) {
        observers.push_back(observer);
    }

    void advance() {
        state = state->next();
        notifyObservers();
    }

    void forceState(shared_ptr<SignalState> newState) {
        state = newState;
        notifyObservers();
    }

    SignalColor getCurrentColor() { return state->getColor(); }

    int getCurrentDurationSeconds() { return timingStrategy->getDurationSeconds(state->getColor()); }
};

class IntersectionController {
private:
    shared_ptr<TrafficSignal> northSouthSignal;
    shared_ptr<TrafficSignal> eastWestSignal;
    int phase;

    void applyPhase() {
        switch (phase) {
            case 0:
                northSouthSignal->forceState(make_shared<GreenState>());
                eastWestSignal->forceState(make_shared<RedState>());
                break;
            case 1:
                northSouthSignal->forceState(make_shared<YellowState>());
                eastWestSignal->forceState(make_shared<RedState>());
                break;
            case 2:
                northSouthSignal->forceState(make_shared<RedState>());
                eastWestSignal->forceState(make_shared<GreenState>());
                break;
            case 3:
                northSouthSignal->forceState(make_shared<RedState>());
                eastWestSignal->forceState(make_shared<YellowState>());
                break;
        }
    }

public:
    IntersectionController(shared_ptr<TrafficSignal> ns, shared_ptr<TrafficSignal> ew)
        : northSouthSignal(ns), eastWestSignal(ew), phase(0) {
        applyPhase();
    }

    void step() {
        phase = (phase + 1) % 4;
        applyPhase();
    }
};

int main() {
    shared_ptr<SignalTimingStrategy> strategy = make_shared<FixedTimingStrategy>();
    auto northSouth = make_shared<TrafficSignal>("NS-1", strategy);
    auto eastWest = make_shared<TrafficSignal>("EW-1", strategy);

    northSouth->addObserver(make_shared<PedestrianSignal>("NS-Crossing"));
    eastWest->addObserver(make_shared<PedestrianSignal>("EW-Crossing"));

    IntersectionController controller(northSouth, eastWest);

    for (int i = 0; i < 4; i++) {
        cout << "Phase " << i << ": NS=" << colorName(northSouth->getCurrentColor())
             << " (" << northSouth->getCurrentDurationSeconds() << "s), EW="
             << colorName(eastWest->getCurrentColor()) << " ("
             << eastWest->getCurrentDurationSeconds() << "s)" << endl;
        controller.step();
    }

    return 0;
}
